/* ==UserStyle==
@name         Shark Emo Theme
@namespace    userstyles.org
@version      1.0.0
@description  A dark shark and emo theme with deep ocean colors and sharp edges.
==/UserStyle== */

/* Deep ocean dark background and bright red text for an emo look */
body {
    background-color: #0b131a !important;
    color: #ff3333 !important;
    font-family: "Courier New", Courier, monospace !important;
}

/* Links look like sharp shark teeth and turn neon red when you hover */
a {
    color: #0088cc !important;
    text-decoration: none !important;
    border-bottom: 2px dashed #ff3333 !important;
}

a:hover {
    color: #ff0000 !important;
    cursor: crosshair !important;
}

/* Boxes have sharp corners and a dark blue borders */
div, section, article {
    background-color: #05090d !important;
    border: 2px solid #1a2f40 !important;
    border-radius: 0px !important;
}

/* Custom scrollbar that looks like a dark fin moving down the page */
::-webkit-scrollbar {
    width: 12px !important;
    background: #05090d !important;
}

::-webkit-scrollbar-thumb {
    background: #1a2f40 !important;
    border: 1px solid #ff3333 !important;
}
